architecture.h4_f:
رسالة = CBOR{الخامس:1، نص، رد_إلى، مرسل_في}
ct = AES-GCM-256-تشفير(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {نص مشفر: سداسي عشري (ct)، nonce: سداسي عشري}

cryptoWire.h1_f:
pt = CBOR{v:1، نص، رد_على؟، معرف_الخيط؟، ذكر؟، إرسال_ات}
ct = AES-GCM-256-تشفير(room_key, nonce, pt, aad=hex(room_id))
السلك = CBOR{
  الخامس: 1،
  النص المشفر: سداسي عشري (ct)، // طول متغير
  الرقم: سداسي عشري (12 ب)،
  sender_pseudo: سداسي عشري (16 ب)،
  send_at: unix_ms
}

cryptoWire.h5_f:
الخارجي = CBOR{
  عقدة المصدر: hex32،
  الهدف_المستخدم: int64،
  نص التشفير الداخلي: بايت،
  Internal_nonce: بايت،
  send_at: unix_ms
}
سيج = Ed25519-تسجيل (source_priv، الخارجي)
POST /federation/deliver { الظرف: خارجي، التوقيع: hex64 }

auth.h1_f:
POST /api/authentication/register
  { اسم المستخدم، كلمة المرور، x25519_public_key، اسم العرض، الهاتف؟، البريد الإلكتروني؟، avatar_emoji }

الرد 201 تم الإنشاء:
  { رمز الوصول، رمز التحديث، معرف المستخدم، اسم المستخدم، ... }

auth.h3_f:
حمولة Access_token:
  { فرعي: user_id، JTI: معرف_الجهاز، النوع: "الوصول"، EXP: الآن + 15 دقيقة }
حمولة Refresh_token:
  { فرعي: user_id، jti: معرف_الجهاز، النوع: "تحديث"، exp: الآن + 30d }

HS256- تم التوقيع عليه بسر 64 بايت للعقدة من .env

auth.h4_f:
Register_begin (): التحدي = راند (32)
                    الخيارات = { rp.id، user.id، pubKeyCredParams، التحدي }
                    خيارات العودة

تسجيل_فينيش (شهادة):
  التحقق من التصديق مقابل TPM / Secure Enclave root CA
  المتجر {credential_id، public_key، العداد: 0}

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128 بت سداسي عشري، ttl: 60 }
QR الحمولة = { nonce، user_id، الخادم: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → تم تسجيل جهاز جديد؛ عادت JWTs.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 سداسي عشري
نص مشفر = AES-GCM-تشفير(room_key, nonce, CBOR_payload, aad=room_id)

إطار مروحي للخارج: { النوع: "m"، غرفة، رسالة: {id، ct، nonce، sender_pseudo، send_at} }

files.h2_f:
الحرف الأول POST /api/files/resumable/init {اسم الملف، الحجم، قطعة_حجم_تلميح}
            ← {upload_id، قطعة_حجم}
قطعة PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
وضع اللمسات الأخيرة POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id، url}
TTL على غير مكتمل : 24 ساعة

files.h4_f:
قائمة الرفض = {
  "التطبيق/x-dosexec"،
  "التطبيق/x-sharedlib"،
  "التطبيق/x-ماخ ثنائي"،
}
إذا كان magic.from_buffer(buf[:1024]) في Den_list: قم بإرجاع 415

presence.h1_f:
العميل: عند الضغطة الأولى على المفتاح → أرسل {النوع:"t"، الحالة:"بدء"}
         لا مزيد من الإرسال لمدة 3 ثوان ما لم تتغير الحالة
         10 ثوانٍ بعد آخر ضغطة على المفتاح → أرسل {النوع:"t"، الحالة:"إيقاف"}
جهاز الاستقبال: توقف تلقائي لمدة 10 ثوانٍ بعد "البدء" الأخير في حالة عدم وصول "التوقف".

calls.h1_f:
POST /api/calls/{room_id}/بدء {فيديو، صوت} → call_id
WS بث {النوع:"ج"، النوع:"دعوة"، call_id}
WS بث {النوع:"ج"، النوع:"عرض"، sdp}
WS البث {النوع:"ج"، النوع:"إجابة"، sdp}
WS بث {النوع:"ج"، النوع:"مرشح"،آيس} × ن
POST /api/calls/{call_id}/end

federation.h2_f:
المغلف = {
  عقدة المصدر: hex32،
  الهدف_المستخدم: int64،
  نص التشفير الداخلي: بايت،
  Internal_nonce: بايت،
  send_at: unix_ms،
}
سيج = Ed25519Sign(source_priv, CBOR(الظرف))
POST /federation/deliver { مغلف، سيج }

gossip.h3_f:
الإعلان = {pubkey، نقطة النهاية، المعلن عنها_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(إعلان))
حمولة القيل والقال: [...، {ad، sig}، ...]

المتلقي: تحقق من التوقيع مقابل ad.pubkey → قم بالتخزين إذا كان موافقًا
إضافي: إثبات العمل لـ 2^18 من الأصفار البادئة على {pubkey, endpoint}

stealth.h2_f:
وحدات بايت ClientHello = chrome_120_template مع {
  عشوائي = عشوائي لدينا،
  server_name = اسم المضيف الخاص بنا (أو ECH-ملفوف)،
  session_id = معرف جلستنا،
}
JA4 = t13d_xxxx_xxxx_xxxx (يتطابق مع الإصدار الثابت الحالي من Chrome)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {الاسم: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: المجال(t) = base32( SHA256(البذرة ∥ YYYY-MM-DD)) )[:16] + ".مثال"

push.h4_f:
iOS NSE: didReceive(request) { decrypt(request.content.userInfo) }
أندرويد FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
الويب SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
الأداة =sign_tool
الإدخال = شجرة المصدر، المفاتيح/release.key
بيان = {
  الإصدار: "0.1.0"،
  build_at: unix_ms،
  الملفات: [{المسار، sha256، الحجم}، ...]
}
sig = Ed25519-Sign(release_priv, CBOR(البيان))
الإخراج = INTEGRITY.sig.json = {البيان، موقع بواسطة: pub_hex، sig: sig_hex}

bots.h1_f:
إنشاء: POST /api/bots {اسم المستخدم، اسم العرض، الكود}
          → {bot_id، الرمز المميز، مفتاح النشر}
تشغيل: قيد التشغيل (كوروتين داخل العقدة)
      OR خارجي (استطلاع طويل /api/bots/{id}/updates, token-auth'd)
الرسالة: {نص، التوقيع: Ed25519-Sign(bot_priv, canonical_msg)}

