sig = Ed25519-Sign(source_priv, CBOR(envelope))
POST /federation/deliver {envelope, sig}
يتحقق B: sig ضد الاتحادات[source_node].pubkey

fts5.h1_f:
CREATE VIRTUAL TABLE messages_fts USING fts5(
  المحتوى - عمود مميز
  معرف الغرفة UNINDEXED،
  الرمز المميز = 'unicode61 Remove_diacritics 2'
);
الاستعلام: SELECT رويد FROM messages_fts WHERE المحتوى MATCH 'foo'

